from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(4,'english','together-we-can','Together We Can',
 ('Teamwork','A cheerful poem says that when we stand together, help each other, share wins and losses and trust each other, the team can overcome anything. In this chapter you will read the poem, talk about teamwork and unity, learn the special words for groups such as a herd, a pack and a swarm, use words like behind, between, near and in front of, and write about what people will do next.'),
 [('The poem on teamwork',['The poem says that when we stand together we are strong, and when we help each other we never fall.','It says that teams cheer aloud, win or lose, and always share and trust each other.','Each joined hand brings the goal nearer, and team spirit fills the air with cheer.','The message is that together we can do more than we can alone, and that the joy of a team is in working as one.']),
  ('Thinking and talking',['Joining hands with your team makes everyone feel safe and strong, because you know others are with you.','Helping each other is important because everyone is good at something different and a job is done faster together.','If two teammates disagree, a good leader listens to both, finds what they agree on and helps them work together again.','If you lose a game you may feel sad, but you can learn from it and play better next time, and you can still be friendly with the winners.']),
  ('Speaking about our land',['Bokali and Darsana love their country. They say that we have different traditions, food, festivals and languages, but we still stand in unity.','Unity in diversity means that people can be different and still be one country.','You can tell a friend: Hello, I am Meena. My favourite food is idli. My favourite festival is Pongal. In this festival we cook and share sweet pongal.','When you talk in pairs, take turns: one speaks and the other listens, then change.']),
  ('Group words',['We use special names for groups of animals, people and things.','A bundle of sticks, a herd of sheep, a pack of wolves, a bouquet of flowers, a grove of trees, a swarm of bees, a choir of boys and a bunch of keys.','A bouquet is made of flowers tied together, a grove is a small group of trees, and a choir is a group of singers.','Honeybees work as a team: a waggle dance tells the hive where flowers with nectar are. Ants also use signals to find food and build nests together.']),
  ('Where is it? Position words',['On the map the post office, hospital, bank, school, bookstore and children\'s park are in different places.','Behind means at the back of something. In front of means before it, facing it. Near means close to it. Between means in the middle of two things.','The post office is behind the hospital, the bookstore is near the children\'s park, and an ambulance stands between the post office and the hospital.','Always look at the map first and then choose the word that fits.']),
  ('Telling what will happen next',['The word will helps us talk about things that are going to happen in the future.','Lubang is helping his injured friend, and they will go to the doctor next.','Anna is helping an old lady, and the old lady will thank her. Students are working together, and the teacher will praise them.','First say what is happening now, then say what will happen next using will.']),
  ('A symbol of togetherness',['Fold a sheet of paper, draw one side of a body with head, neck, hand, dress, leg and shoe, and cut along the drawing.','Unfold it and you will have a whole figure, with matching sides, like two people holding hands. Colour it as you like.','Paste a picture of what you have made as your symbol of togetherness.'])],
 [('Choose the group word: a ___ of bees.',[('Think about bees flying together.','A big flying group of bees has a special name.'),('The word is swarm.','Swarm is used for bees.'),('So: a swarm of bees.','Herd is for sheep and pack is for wolves.')]),
  ('Use behind, between, near or in front of: The ambulance is ___ the post office and the hospital.',[('The ambulance is in the middle of two buildings.','Middle of two things means between.'),('So: The ambulance is between the post office and the hospital.','Behind would mean at the back of only one.')]),
  ('Write what will happen: Anna is helping the old lady cross the road.',[('Say what is happening now.','Anna is helping the old lady.'),('Add what happens next with will.','The old lady will thank Anna.'),('So the sentence is: The old lady will thank Anna.','Will talks about the future.')])],
 ('Say what the poem teaches about teamwork and give one example of unity in our country.',['Together we are strong','Helping and sharing','Win or lose, we trust each other','Different festivals and foods, one country'],['Only the winner matters','Teams do not need trust']),
 ['Teamwork makes us stronger.','Unity means people can be different and still stand together.','A herd, a pack, a swarm, a bouquet, a grove, a choir and a bunch are group words.','Behind, between, near and in front of tell the position of things.','Will is used to talk about what happens next.'],
 [M('1',1,'What happens when we join hands in a team, according to the poem?','The goal comes near',[('We lose the game','The poem says the goal is near'),('We stop playing','The poem is about teamwork')],'Each joined hand brings the goal nearer.'),
  M('2',1,'Why is helping each other important?','We can do more together',[('We can win without effort','The poem says together'),('It is easy to do alone','Teamwork matters')],'Together we are stronger and finish faster.'),
  M('3',1,'What do Bokali and Darsana say about our country?','We have many differences but stand in unity',[('Everyone is the same','They mention differences'),('We do not like festivals','They like them')],'We have many traditions and still stand together.'),
  M('4',2,'Which group word goes with sheep?','herd',[('pack','Pack is for wolves'),('swarm','Swarm is for bees')],'A herd of sheep.'),
  M('5',2,'Which group word goes with wolves?','pack',[('herd','Herd is for sheep'),('bunch','Bunch is for keys or bananas')],'A pack of wolves.'),
  M('6',2,'Which group word goes with trees?','grove',[('choir','A choir is singers'),('bouquet','A bouquet is flowers')],'A grove of trees.'),
  M('7',2,'Which group word goes with boys who sing?','choir',[('swarm','Swarm is for bees'),('pack','Pack is for wolves')],'A choir sings together.'),
  M('8',2,'The bank is ___ the school (at the back of it). Which word fits?','behind',[('between','Between needs two things'),('in front of','That means before it')],'Behind means at the back.'),
  M('9',2,'Which sentence talks about the future?','The teacher will praise them.',[('The teacher praised them.','That is the past'),('The teacher is praising them.','That is now')],'Will shows what happens next.'),
  F('10',2,'Honeybees use a waggle dance to tell the hive where flowers are.',True,'The dance tells the exact place of nectar.'),
  F('11',2,'A bouquet is a group of boys.',False,'A bouquet is a group of flowers.'),
  S('12',3,'What word shows that something is going to happen?',['will'],'Will is used for the future.')],
 keep=['bouquet','swarm'])
